// Notion's database-query response comes back as ONE item (the raw
// {results: [...]} object from the HTTP Request node), not one item per
// page -- this node fans it out to one item per Notion row, same idea as
// workflow 32's "Grid to Records" step for Sheet rows. Query filter already
// restricts to rows with a non-empty Email, but the check here is kept as a
// defensive backstop in case that ever changes.

const resp = $input.first().json;
const results = resp.results || [];
const out = [];
for (const page of results) {
  const props = page.properties || {};
  const email = (props['Email'] && props['Email'].email) || '';
  if (!email) continue;
  const nameProp = props['Name'] && props['Name'].title;
  const name = (nameProp && nameProp[0] && nameProp[0].plain_text) || '';
  out.push({
    json: {
      pageId: page.id,
      email: email.toLowerCase().trim(),
      notionName: name,
    },
  });
}
return out;

// Matches each Notion row (from "Flatten Notion rows") against its Firestore
// runQuery result (from "Query Firestore lead by email"), in the SAME order --
// that node fires one call per input item, so queryResults[i] always
// corresponds to notionRows[i]. This node runs once for ALL items (n8n Code
// node default mode) and must return one output item per input item -- see
// workflow 32's "Check Match" node for the exact same pattern and the bug it
// was written to avoid ($input.first()/$(...).item singular only look at
// item 0 and silently drop every row after it).
//
// Currently only 3 of ~200 Do or Wait leads have a matching row in this
// Notion database (it's scoped to eDM-sourced MQLs, not every lead) -- a row
// with no Do or Wait match is expected and just gets skipped, not an error.
//
// Design choice (2026-08-26, per Justin): this is a full-overwrite mirror,
// not an append-only log. Every run recomputes Handoff Status + Outreach
// History from Do or Wait's current state and replaces both fields outright.
// No cursor/dedupe field was added to the leads/{id} schema for this --
// Do or Wait's entries[] is already the source of truth, so re-deriving from
// it each time is simpler and can't drift out of sync with a stale cursor.
//
// NOTE on duplicate leads: a real duplicate-lead bug surfaced here 2026-08-26
// (Robb Williams / Corporate Storage had a stale archived duplicate that a
// naive limit:1 query briefly matched instead of the real active lead --
// see the README's "Known issue" section for the full story). Fixed by
// cleaning up the underlying duplicate data in Do or Wait directly (marked
// dead + merged_into_lead_id, its one real entry merged into the surviving
// lead), NOT by adding duplicate-tolerance logic here -- per Justin,
// "we shouldn't change the n8n workflow to account for a data mess." This
// query stays a plain limit:1 exact-match lookup on purpose.

function fsVal(field) {
  if (!field) return null;
  if (field.stringValue !== undefined) return field.stringValue;
  if (field.integerValue !== undefined) return Number(field.integerValue);
  if (field.doubleValue !== undefined) return field.doubleValue;
  if (field.booleanValue !== undefined) return field.booleanValue;
  if (field.timestampValue !== undefined) return field.timestampValue;
  if (field.nullValue !== undefined) return null;
  if (field.mapValue) { const out = {}; for (const [k, v] of Object.entries(field.mapValue.fields || {})) out[k] = fsVal(v); return out; }
  if (field.arrayValue) return (field.arrayValue.values || []).map(fsVal);
  return null;
}

const STAGE_TO_HANDOFF = {
  lead: 'BD Following Up',
  tour: 'BD Following Up',
  proposal: 'BD Following Up',
  negotiation: 'BD Following Up',
  executed: 'Converted to SQL',
  dead: 'Lost/No Need',
};

const MAX_TEXT_LEN = 1900; // Notion rich_text array elements cap at 2000 chars each

const queryResults = $input.all();
const notionRows = $('Flatten Notion rows').all();

const out = [];
for (let i = 0; i < queryResults.length; i++) {
  const raw = queryResults[i].json;
  const body = Array.isArray(raw) ? raw : [raw];
  const doc = body.find((r) => r && r.document);
  const row = (notionRows[i] && notionRows[i].json) || {};

  if (!doc) {
    out.push({ json: { ...row, matched: false, reason: 'No Do or Wait lead found for this email' } });
    continue;
  }

  const fields = doc.document.fields || {};
  const stage = fsVal(fields.stage) || 'lead';
  const entriesRaw = fsVal(fields.entries) || [];
  const leadId = (doc.document.name || '').split('/').pop();

  const sorted = entriesRaw
    .filter((e) => e && e.kind !== 'note')
    .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));

  let text = '';
  for (const e of sorted) {
    const date = (e.createdAt || '').slice(0, 10);
    const dirTag = e.dir ? '/' + e.dir : '';
    const line = `${date} [${e.kind || 'note'}${dirTag}] ${e.text || ''}`;
    if (text.length + line.length + 1 > MAX_TEXT_LEN) {
      text += '\n...(older entries omitted)';
      break;
    }
    text += (text ? '\n' : '') + line;
  }

  out.push({
    json: {
      ...row,
      matched: true,
      leadId,
      stage,
      handoffStatus: STAGE_TO_HANDOFF[stage] || 'BD Following Up',
      outreachText: text || '(no logged activity yet)',
    },
  });
}
return out;
